class SidebarPresetChecks {
 static readonly BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;static MainWindow main;static ClientSession session;static Application app;static int count;static string output;
 static object Get(string n){return typeof(MainWindow).GetField(n,F).GetValue(main);}static object Call(string n,params object[] a){return typeof(MainWindow).GetMethod(n,F).Invoke(main,a);}static void Check(bool v,string n){if(!v)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}
 static IEnumerable<T> All<T>(DependencyObject r)where T:DependencyObject{for(int i=0;i<VisualTreeHelper.GetChildrenCount(r);i++){var c=VisualTreeHelper.GetChild(r,i);if(c is T)yield return (T)c;foreach(var x in All<T>(c))yield return x;}}
 static void Pump(){var f=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>f.Continue=false));Dispatcher.PushFrame(f);}static void Wait(Func<bool> done){var end=DateTime.UtcNow.AddSeconds(25);while(!done()&&DateTime.UtcNow<end){Pump();Thread.Sleep(5);}if(!done())throw new Exception("Timeout");}static void Finish(Task t){Wait(()=>t.IsCompleted);t.GetAwaiter().GetResult();}static void Click(Button b){b.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Pump();}static void Page(string n){Call("Page",n);Pump();main.UpdateLayout();}
 static T Named<T>(string name)where T:FrameworkElement{return All<T>(main).Single(x=>x.Name==name);}
 static void Save(Window w,string name){w.UpdateLayout();var b=new RenderTargetBitmap((int)w.ActualWidth,(int)w.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(w);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(Path.Combine(output,name+".png")))e.Save(f);}
 static void Dialog(string button,string title,Action<Window> act){Exception error=null;var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=(s,e)=>{var w=app.Windows.Cast<Window>().FirstOrDefault(x=>x!=main&&x.Title==title);if(w==null)return;timer.Stop();try{w.Left=-10000;w.Top=-10000;w.UpdateLayout();act(w);}catch(Exception x){error=x;w.Close();}};timer.Start();Click(Named<Button>(button));timer.Stop();if(error!=null)throw error;}
 static void Accept(Window w){Click(All<Button>(w).Single(b=>Convert.ToString(b.Content)=="Готово"));}
 static void Open(string root){if(app.Resources.Count==0){typeof(MainWindow).Assembly.GetType("Mcrf.Wpf.Program").GetMethod("LoadTheme",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{app});SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());}main=new MainWindow(new[]{"--data",root}){ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual,Left=-10000,Top=-10000,Width=1050,Height=680};main.Show();Wait(()=>Get("session")!=null);session=(ClientSession)Get("session");((DispatcherTimer)Get("health")).Stop();typeof(ClientSession).GetField("catalogTask",F).SetValue(session,Task.FromResult(new ZapretStrategy[0]));main.UpdateLayout();}
 [STAThread]static int Main(string[] args){try{output=args[1];Directory.CreateDirectory(output);app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Open(args[0]);Finish((Task)Call("ChangeInterfaceMode",1));Page("Серверы");
 var behavior=Named<StackPanel>("windowBehavior");Check(behavior.Children[0] is StackPanel&&((StackPanel)behavior.Children[0]).Name=="interfaceSelector","selector is above minimize and close preferences in sidebar");Check(All<ComboBox>(main).Count(s=>s.Name=="interfaceModeChoice")==1,"no duplicate title-bar selector");
 var names=((StackPanel)Get("navigation")).Children.OfType<Button>().Select(b=>Convert.ToString(b.Content)).ToArray();Check(names.SequenceEqual(new[]{"Серверы","Конструктор","Обновления"}),"constructor precedes updates");Check(Named<StackPanel>("serversSections").Children.OfType<Button>().Select(b=>Convert.ToString(b.Content)).SequenceEqual(new[]{"VPN / прокси","VK TURN","Протоколы"}),"VK TURN follows VPN before protocols; WARP hidden in own-VPN mode");
 Click(Named<Button>("serversSection3"));Check(All<ScrollViewer>(main).Any(s=>s.Name=="vkTurnSettingsScroll"),"VK TURN content opens inside Servers tab");Save(main,"vk-turn-tab");Page("Конструктор");Check(!All<CheckBox>(main).Any(c=>c.Name=="simpleAllInternet"||c.Name=="simpleDirectRussia"||c.Name=="simpleDirectTorrents"),"special presets no longer separate switches");
 Dialog("simpleThroughPresets","Через VPN / прокси · пресеты",w=>{All<CheckBox>(w).Single(c=>c.Name=="simpleAllInternet").IsChecked=true;Click(All<Button>(w).Single(b=>Convert.ToString(b.Content)=="Отмена"));});Check(Convert.ToString(Named<Button>("simpleThroughPresets").Content)=="Выбрать пресеты","cancel discards special-preset changes");
 Dialog("simpleThroughPresets","Через VPN / прокси · пресеты",w=>{var c=All<CheckBox>(w).Single(x=>x.Name=="simpleAllInternet");c.IsChecked=true;Save(w,"preset-checkboxes");Accept(w);});
 Dialog("simpleDirectPresets","Напрямую · пресеты",w=>{Check(All<CheckBox>(w).Where(c=>c.Name=="simpleDirectRussia"||c.Name=="simpleDirectTorrents").Count(c=>c.IsChecked==true)==2,"RF and torrents checked within direct preset chooser");Accept(w);});
 Check(Named<TextBox>("simplePresetExtra").IsVisible&&Named<ComboBox>("simpleCustomDirection").IsVisible,"custom domains field and direction always discoverable");Named<TextBox>("simplePresetExtra").Text="direct-only.example\n198.51.100.0/24";Named<ComboBox>("simpleCustomDirection").SelectedIndex=1;Click(Named<Button>("applySimplePresets"));Wait(()=>!(bool)Get("busy"));var r=session.State.Lists.Single(l=>l.BuiltinPreset=="simple-constructor:proxy");Check(r.CustomText==""&&r.DirectCustomText.Contains("direct-only.example")&&!r.Text.Contains("direct-only.example")&&r.ExcludedText.Contains("direct-only.example"),"direct custom entries compile as exclusions and never VPN destinations");Check(!RouteSources.UpdatedText(r,"updated.example").Contains("direct-only.example"),"preset refresh does not reappend direct custom entries into VPN list");Check(VpnPresetRules.DirectRules(new[]{r}).Count>0,"direct custom settings produce actual direct-priority rules");Page("Конструктор");Check(Named<ComboBox>("simpleCustomDirection").SelectedIndex==1&&Named<TextBox>("simplePresetExtra").Text==r.DirectCustomText,"custom direction and input restore when returning");
 var apply=Named<Button>("applySimplePresets");Check(apply.TranslatePoint(new Point(0,apply.ActualHeight),main).Y<=main.ActualHeight-10,"apply button fits minimum window");Save(main,"constructor");
 Named<ComboBox>("simpleCustomDirection").SelectedIndex=0;Named<TextBox>("simplePresetExtra").Text="vpn-only.example";Click(apply);Wait(()=>!(bool)Get("busy"));r=session.State.Lists.Single(l=>l.BuiltinPreset=="simple-constructor:proxy");Check(r.CustomText=="vpn-only.example"&&r.DirectCustomText==""&&!r.ExcludedText.Contains("direct-only.example"),"switching custom direction removes old direct entry and saves through custom text");
 Finish((Task)Call("ChangeInterfaceMode",0));Page("Серверы");Check(Named<StackPanel>("serversSections").Children.OfType<Button>().Select(b=>Convert.ToString(b.Content)).SequenceEqual(new[]{"VPN / прокси","VK TURN","WARP","Протоколы"}),"standard tabs preserve WARP and include TURN");Save(main,"servers-standard");Call("RequestExit");Wait(()=>(bool)Get("closing")&&!main.IsVisible);Open(args[0]);Finish((Task)Call("ChangeInterfaceMode",1));Page("Конструктор");Check(Named<TextBox>("simplePresetExtra").Text=="vpn-only.example"&&Named<ComboBox>("simpleCustomDirection").SelectedIndex==0,"encrypted state restores custom fields after process-window restart");Call("RequestExit");Wait(()=>(bool)Get("closing")&&!main.IsVisible);app.Shutdown();Console.WriteLine("RESULT "+count+" checks PASS; no TUN, VK, hosts or user profile changes");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);if(main!=null)Call("RequestExit");return 1;}}
}
